#include <iostream>
using namespace std;

int digits(int n) {
    if (n < 10) {
        return 1;
    }
    return 1 + digits(n / 10);
}

int main() {
    int n = 0;
    cin >> n;

    cout << n << " 一共有 " << digits(n) << " 位数{tail}" << endl;
    return 0;
}
